import math


class IndependentStrategySlots(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_bars = RollingWindow[TradeBar](201)
        self.aapl_closes = RollingWindow[float](15)

        self.aapl_avg_gain = 0.0
        self.aapl_avg_loss = 0.0
        self.aapl_rsi = None
        self.aapl_changes = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

        self.order_lots = {}

    def OnData(self, data: Slice):
        # Market-state quantities continue updating whenever their own bars exist.
        if data.Bars.ContainsKey(self.spy):
            self.spy_bars.Add(data.Bars[self.spy])

        if data.Bars.ContainsKey(self.aapl):
            self.UpdateAaplRsi(data.Bars[self.aapl].Close)

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        # Strategy A: sell before buy.
        if self.strategy_a_lot > 0 and not self.strategy_a_pending:
            if self.spy_bars.Count >= 51:
                spy_close = self.spy_bars[0].Close
                spy_sma50_today = sum(self.spy_bars[i].Close for i in range(50)) / 50.0
                spy_sma50_yesterday = sum(self.spy_bars[i].Close for i in range(1, 51)) / 50.0
                spy_yesterday_close = self.spy_bars[1].Close

                if spy_yesterday_close >= spy_sma50_yesterday and spy_close < spy_sma50_today:
                    self.SubmitLotOrder(self.spy, -self.strategy_a_lot, "A")
                    self.strategy_a_pending = True

        if self.strategy_a_lot == 0 and not self.strategy_a_pending:
            if self.spy_bars.Count >= 201:
                spy_close = self.spy_bars[0].Close
                spy_sma200_today = sum(self.spy_bars[i].Close for i in range(200)) / 200.0
                spy_sma200_yesterday = sum(self.spy_bars[i].Close for i in range(1, 201)) / 200.0
                spy_yesterday_close = self.spy_bars[1].Close

                if spy_yesterday_close <= spy_sma200_yesterday and spy_close > spy_sma200_today:
                    quantity = int(math.floor((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close))
                    if quantity > 0:
                        self.SubmitLotOrder(self.spy, quantity, "A")
                        self.strategy_a_pending = True

        # Strategy B: sell before buy.
        if self.strategy_b_lot > 0 and not self.strategy_b_pending:
            if self.aapl_rsi is not None and self.aapl_rsi > 60:
                self.SubmitLotOrder(self.aapl, -self.strategy_b_lot, "B")
                self.strategy_b_pending = True

        if self.strategy_b_lot == 0 and not self.strategy_b_pending:
            if self.aapl_closes.Count >= 15:
                red_three_days = (
                    self.aapl_closes[0] < self.aapl_closes[1]
                    and self.aapl_closes[1] < self.aapl_closes[2]
                    and self.aapl_closes[2] < self.aapl_closes[3]
                )

                if red_three_days and self.Portfolio.Cash >= 20_000:
                    quantity = int(math.floor(20_000 / self.aapl_closes[0]))
                    if quantity > 0:
                        self.SubmitLotOrder(self.aapl, quantity, "B")
                        self.strategy_b_pending = True

    def UpdateAaplRsi(self, close):
        if self.aapl_closes.Count > 0:
            change = close - self.aapl_closes[0]
            gain = max(change, 0.0)
            loss = max(-change, 0.0)
            self.aapl_changes += 1

            if self.aapl_changes <= 14:
                self.aapl_avg_gain += gain
                self.aapl_avg_loss += loss

                if self.aapl_changes == 14:
                    self.aapl_avg_gain /= 14.0
                    self.aapl_avg_loss /= 14.0
                    self.aapl_rsi = self.CalculateRsi()
            else:
                self.aapl_avg_gain = ((self.aapl_avg_gain * 13.0) + gain) / 14.0
                self.aapl_avg_loss = ((self.aapl_avg_loss * 13.0) + loss) / 14.0
                self.aapl_rsi = self.CalculateRsi()

        self.aapl_closes.Add(close)

    def CalculateRsi(self):
        if self.aapl_avg_loss == 0:
            return 100.0
        if self.aapl_avg_gain == 0:
            return 0.0
        relative_strength = self.aapl_avg_gain / self.aapl_avg_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def SubmitLotOrder(self, symbol, quantity, lot_name):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_lots[ticket.OrderId] = lot_name

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            return

        lot_name = self.order_lots.get(order_event.OrderId)
        if lot_name == "A":
            self.strategy_a_lot += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_pending = False
                self.order_lots.pop(order_event.OrderId, None)
        elif lot_name == "B":
            self.strategy_b_lot += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_pending = False
                self.order_lots.pop(order_event.OrderId, None)
