class IndependentSlotsAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.SetWarmUp(201, Resolution.Daily)

        self.spy_closes = RollingWindow[float](201)
        self.aapl_closes = RollingWindow[float](15)

        self.red_streak = 0
        self.rsi_changes = []
        self.rsi_ready = False
        self.avg_gain = 0.0
        self.avg_loss = 0.0
        self.rsi_value = 0.0

        self.a_lot = 0
        self.b_lot = 0
        self.a_buy_pending = False
        self.a_sell_pending = False
        self.b_buy_pending = False
        self.b_sell_pending = False
        self.order_info = {}

    def OnData(self, slice: Slice):
        if not all(slice.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_close = float(slice.Bars[self.spy].Close)
        aapl_close = float(slice.Bars[self.aapl].Close)

        previous_aapl_close = self.aapl_closes[0] if self.aapl_closes.Count > 0 else None

        self.spy_closes.Add(spy_close)
        self.aapl_closes.Add(aapl_close)

        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.red_streak += 1
            else:
                self.red_streak = 0

            change = aapl_close - previous_aapl_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if not self.rsi_ready:
                self.rsi_changes.append((gain, loss))
                if len(self.rsi_changes) == 14:
                    self.avg_gain = sum(x[0] for x in self.rsi_changes) / 14.0
                    self.avg_loss = sum(x[1] for x in self.rsi_changes) / 14.0
                    self.rsi_ready = True
            else:
                self.avg_gain = (self.avg_gain * 13.0 + gain) / 14.0
                self.avg_loss = (self.avg_loss * 13.0 + loss) / 14.0

            if self.rsi_ready:
                if self.avg_loss == 0:
                    self.rsi_value = 100.0
                else:
                    self.rsi_value = 100.0 - 100.0 / (1.0 + self.avg_gain / self.avg_loss)

        if self.IsWarmingUp:
            return

        spy_ready = self.spy_closes.Count == 201
        aapl_ready = self.rsi_ready and self.aapl_closes.Count >= 4

        # Sells are evaluated before buys.
        if spy_ready and self.a_lot > 0 and not self.a_sell_pending:
            today_sma50 = sum(self.spy_closes[i] for i in range(50)) / 50.0
            yesterday_sma50 = sum(self.spy_closes[i] for i in range(1, 51)) / 50.0

            if self.spy_closes[1] >= yesterday_sma50 and spy_close < today_sma50:
                self._submit_order("a_sell", self.spy, -self.a_lot)

        if aapl_ready and self.b_lot > 0 and not self.b_sell_pending:
            if self.rsi_value > 60.0:
                self._submit_order("b_sell", self.aapl, -self.b_lot)

        if spy_ready and self.a_lot == 0 and not self.a_buy_pending:
            today_sma200 = sum(self.spy_closes[i] for i in range(200)) / 200.0
            yesterday_sma200 = sum(self.spy_closes[i] for i in range(1, 201)) / 200.0

            if self.spy_closes[1] <= yesterday_sma200 and spy_close > today_sma200:
                shares = int(math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close))
                if shares > 0:
                    self._submit_order("a_buy", self.spy, shares)

        if aapl_ready and self.b_lot == 0 and not self.b_buy_pending:
            if self.red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                shares = int(math.floor(20_000.0 / aapl_close))
                if shares > 0:
                    self._submit_order("b_buy", self.aapl, shares)

    def _submit_order(self, kind, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=kind)
        self.order_info[ticket.OrderId] = kind

        if kind == "a_buy":
            self.a_buy_pending = True
        elif kind == "a_sell":
            self.a_sell_pending = True
        elif kind == "b_buy":
            self.b_buy_pending = True
        elif kind == "b_sell":
            self.b_sell_pending = True

    def OnOrderEvent(self, order_event):
        kind = self.order_info.get(order_event.OrderId)
        if kind is None:
            return

        if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            fill_quantity = order_event.FillQuantity

            if kind.startswith("a_"):
                self.a_lot = max(0, self.a_lot + fill_quantity)
            else:
                self.b_lot = max(0, self.b_lot + fill_quantity)

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if kind == "a_buy":
                self.a_buy_pending = False
            elif kind == "a_sell":
                self.a_sell_pending = False
            elif kind == "b_buy":
                self.b_buy_pending = False
            elif kind == "b_sell":
                self.b_sell_pending = False

            self.order_info.pop(order_event.OrderId, None)
